func TestEvalCaseContextCancelExpiredDeadline2(t *testing.T) {
ctx,cancel:=context.WithDeadline(context.Background(),time.Now().Add(-20*time.Millisecond));defer cancel()
    if e:=WaitForCancel(ctx);e!=ctx.Err()||e!=context.DeadlineExceeded{t.Fatal(e)}
}
